function census(text,file){
 const sf=ts.createSourceFile(file,text,ts.ScriptTarget.Latest,true),found={};
 function visit(n){
  if(ts.isCallExpression(n)&&["test","it"].includes(root(n.expression))&&title(n)!==null){
